package com.game_manager.gm.machine;import com.game_manager.gm.station.GamingStationProfileRepository;import java.time.Clock;import lombok.RequiredArgsConstructor;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component@RequiredArgsConstructor public class StationEnforcementStaleJob {private final StationClientEnforcementRepository states;private final StationHeartbeatRepository heartbeats;private final GamingStationProfileRepository stations;private final Clock clock;
 @Scheduled(fixedDelayString="${app.gaming-session.heartbeat-interval-seconds:10}000")@Transactional public void markStale(){var now=clock.instant();for(var state:states.findAll()){if(state.getEnforcementStatus()==StationEnforcementStatus.LOCK_PENDING||state.getEnforcementStatus()==StationEnforcementStatus.LOCKED)continue;var station=stations.findByResourceId(state.getStationId()).orElse(null);var heartbeat=heartbeats.findById(state.getStationId()).orElse(null);if(station!=null&&(heartbeat==null||!heartbeat.getLastSeenAt().plusSeconds(station.getOfflineGraceSeconds()).isAfter(now))){state.setEnforcementStatus(StationEnforcementStatus.OFFLINE);state.setReason("Heartbeat stale");}}}
}
